function tagUnit<Fn extends (...args: any[]) => any, Branded>(name: string, fn: Fn, unitLayer: string): Branded {
  function unit(...args: any[]) {
    return fn(...args);
  }
  Object.defineProperty(unit, 'name', {
    value: name,
    configurable: true
  });
  return Object.assign(unit, {
    unitName: name,
    unitLayer
  }) as unknown as Branded;
}

