function defineProvider<Props extends Forbid<Props, ProviderAllowed>, Value>(name: string, fn: (props: Props) => Value): ProviderUnit<Props, Value> {
  const Context = React.createContext<{
    value: Value;
  } | typeof NOT_PROVIDED>(NOT_PROVIDED);
  Context.displayName = name;
  function ProviderComponent(props: Props & {
    children?: React.ReactNode;
  }): JSX.Element {
    const {
      children,
      ...rest
    } = props;
    const value = fn(rest as Props);
    return React.createElement(Context.Provider, {
      value: {
        value
      }
    }, children as React.ReactNode);
  }
  Object.defineProperty(ProviderComponent, 'name', {
    value: `${name}ProviderComponent`,
    configurable: true
  });
  function useProvider(): Value {
    const ctx = React.useContext(Context);
    when(equals(ctx, NOT_PROVIDED), () => {
      fail(errorFrom(join(`${name}: useProvider() was called outside its ProviderComponent's subtree -- render `, `${name}ProviderComponent somewhere above the component calling useProvider().`)));
    });
    return (ctx as {
      value: Value;
    }).value;
  }
  Object.defineProperty(useProvider, 'name', {
    value: `use${name}Provider`,
    configurable: true
  });
  return {
    ProviderComponent,
    useProvider,
    unitName: name,
    unitLayer: 'hook'
  } as unknown as ProviderUnit<Props, Value>;
}

function ProviderComponent(props: Props & {
  children?: React.ReactNode;
}): JSX.Element {
  const {
    children,
    ...rest
  } = props;
  const value = fn(rest as Props);
  return React.createElement(Context.Provider, {
    value: {
      value
    }
  }, children as React.ReactNode);
}

function useProvider(): Value {
  const ctx = React.useContext(Context);
  when(equals(ctx, NOT_PROVIDED), () => {
    fail(errorFrom(join(`${name}: useProvider() was called outside its ProviderComponent's subtree -- render `, `${name}ProviderComponent somewhere above the component calling useProvider().`)));
  });
  return (ctx as {
    value: Value;
  }).value;
}

function normalizeIssues(issues: ReadonlyArray<StandardSchemaIssue>): SchemaIssue[] {
  return mapEach(issues, issue => ({
    message: textFrom(issue.message),
    path: mapEach(orElse(issue.path, () => []), segment => when(and(equals(typeof segment, 'object'), () => differs(segment, null)), () => segment.key, () => segment))
  }));
}

function schemaError(issues: ReadonlyArray<SchemaIssue>): ServiceResult<never> {
  return {
    status: 'error',
    kind: 'schema',
    issues
  };
}

function isThenable(value: unknown): value is PromiseLike<unknown> {
  return and(and(equals(typeof value, 'object'), () => differs(value, null)), () => equals(typeof (value as {
    then?: unknown;
  }).then, 'function'));
}

function checkResponse<S extends ResponseSchema>(schema: S, value: unknown): ServiceResult<SchemaOutput<S>> | Promise<ServiceResult<SchemaOutput<S>>> {
  type Out = SchemaOutput<S>;
  const toResult = (r: StandardSchemaResult<unknown>): ServiceResult<Out> => when(r.issues, () => schemaError(normalizeIssues(r.issues)), () => ({
    status: 'ok',
    value: r.value as Out
  }));
  return attempt(() => when('~standard' in schema, () => {
    const raw = schema['~standard'].validate(value);
    return when(isThenable(raw), () => thenPromise(resolvePromise(raw), toResult, (e: unknown) => schemaError([{
      message: `schema threw: ${describe(e)}`,
      path: []
    }])), () => toResult(raw));
  }, () => {
    const parsed = schema.safeParse(value);
    return when(parsed.success, () => ({
      status: 'ok',
      value: parsed.data as Out
    }), () => schemaError(normalizeIssues(parsed.error.issues)));
  }), e => schemaError([{
    message: `schema threw: ${describe(e)}`,
    path: []
  }]));
}

function toResult(r: StandardSchemaResult<unknown>): ServiceResult<Out> {
  return when(r.issues, () => schemaError(normalizeIssues(r.issues)), () => ({
    status: 'ok',
    value: r.value as Out
  }));
}

function checkServiceReturn<S extends ResponseSchema>(schema: S, raw: unknown): ServiceResult<SchemaOutput<S>> | Promise<ServiceResult<SchemaOutput<S>>> {
  return when(isThenable(raw), () => thenPromise(resolvePromise(raw), v => checkResponse(schema, v)), () => {
    const result = checkResponse(schema, raw);
    return when(isThenable(result), () => {
      // Nothing can await this; settle it quietly so an async validator's own rejection never
      // surfaces as an unhandled rejection either.
      thenPromise(resolvePromise(result), undefined, () => undefined);
      return schemaError([{
        message: 'schema validates asynchronously but the service returned synchronously; make the service async (return a Promise) or use a synchronous schema',
        path: []
      }]);
    }, () => result);
  });
}

function describe(e: unknown): string {
