function isCurrent(state: AsyncState<unknown>, request: number | undefined): boolean {
  return when(not(state.fetching), () => false, () => when(equals(request, undefined), () => true, () => equals(request, state.request)));
}

init() {
  return {
    status: 'idle',
    data: null,
    error: null,
    fetching: false,
    request: 0,
    updatedAt: null
  };
}

send(state, event) {
  return match(event.type, {
    FETCH: () => when(equals(state.status, 'success'), () => ({
      ...state,
      fetching: true,
      request: state.request + 1
    }), () => ({
      ...state,
      status: 'pending',
      error: null,
      fetching: true,
      request: state.request + 1
    })),
    RESOLVE: () => when(not(isCurrent(state, event.request)), () => state, () => ({
      ...state,
      status: 'success',
      data: event.data,
      error: null,
      fetching: false,
      updatedAt: orElse(event.at, () => null)
    })),
    REJECT: () => when(not(isCurrent(state, event.request)), () => state, () => ({
      ...state,
      status: 'error',
      error: event.error,
      fetching: false
    })),
    RESET: () => machine.init()
  }, () => state);
}

stateOf(state) {
  return state.status;
}

async function loadAsync<D>(state: AsyncState<D>, load: () => Promise<D>, now: () => number = () => nowTime()): Promise<AsyncState<D>> {
  const started = machine.send(state, {
    type: 'FETCH'
  }) as AsyncState<D>;
  return await attemptAsync(async () => {
    const data = await load();
    return machine.send(started, {
      type: 'RESOLVE',
      data,
      request: started.request,
      at: now()
    }) as AsyncState<D>;
  }, async error => machine.send(started, {
    type: 'REJECT',
    error,
    request: started.request
  }) as AsyncState<D>);
}

function flags(state: AsyncState<unknown>): {
  isLoading: boolean;
  isError: boolean;
  isSuccess: boolean;
  isRefetching: boolean;
} {
  return {
    isLoading: equals(state.status, 'pending'),
    isError: equals(state.status, 'error'),
    isSuccess: equals(state.status, 'success'),
    isRefetching: and(equals(state.status, 'success'), () => state.fetching)
  };
}

function pageCount(total: number, pageSize: number): number {
  return when(atMost(total, 0), () => 1, () => ceilingOf(dividedBy(total, pageSize)));
}

function clampPage(pageIndex: number, total: number, pageSize: number): number {
  const last = minus(pageCount(total, pageSize), 1);
  return when(lessThan(pageIndex, 0), () => 0, () => when(greaterThan(pageIndex, last), () => last, () => floorOf(pageIndex)));
}

function positionOf(pageIndex: number, total: number, pageSize: number): PagePosition {
  const count = pageCount(total, pageSize);
  return when(atMost(total, 0), () => 'empty', () => when(equals(count, 1), () => 'only', () => when(equals(pageIndex, 0), () => 'first', () => when(equals(pageIndex, minus(count, 1)), () => 'last', () => 'middle'))));
}

function at(pageIndex: number, total: number, pageSize: number): PageState {
  const index = clampPage(pageIndex, total, pageSize);
  return {
    status: positionOf(index, total, pageSize),
    pageIndex: index,
    pageSize,
    total
  };
}

function sliceBounds(state: PageState): {
  start: number;
  end: number;
} {
  const start = times(state.pageIndex, state.pageSize);
  return {
    start,
    end: smallestOf([plus(start, state.pageSize), state.total])
  };
}

function pageItems<T>(rows: T[], state: PageState): T[] {
  const {
    start,
    end
  } = sliceBounds(state);
  return part(rows, start, end);
}

function canNext(state: PageState): boolean {
  return or(equals(state.status, 'first'), () => equals(state.status, 'middle'));
}

function canPrevious(state: PageState): boolean {
  return or(equals(state.status, 'middle'), () => equals(state.status, 'last'));
}

init(input) {
  return at(orElse(input.pageIndex, () => 0), input.total, orElse(input.pageSize, () => 10));
}

send(state, event) {
  return match(event.type, {
    NEXT: () => when(not(canNext(state)), () => state, () => at(state.pageIndex + 1, state.total, state.pageSize)),
    PREVIOUS: () => when(not(canPrevious(state)), () => state, () => at(minus(state.pageIndex, 1), state.total, state.pageSize)),
    GO_TO: () => {
      const next = at(event.pageIndex, state.total, state.pageSize);
      return when(equals(next.pageIndex, state.pageIndex), () => state, () => next);
    },
    SET_PAGE_SIZE: () => when(event.pageSize < 1, () => state, () => {
      // Keep the first row of the current page on screen.
      const firstRow = times(state.pageIndex, state.pageSize);
      return at(floorOf(dividedBy(firstRow, event.pageSize)), state.total, event.pageSize);
    }),
    SET_TOTAL: () => at(state.pageIndex, event.total, state.pageSize)
  }, () => state);
}

stateOf(state) {
  return state.status;
}

function paginate<T>(rows: T[], pageIndex: number, pageSize: number): {
  items: T[];
  pageIndex: number;
  pageCount: number;
  canNext: boolean;
  canPrevious: boolean;
} {
  const state = machine.init({
    total: lengthOf(rows),
    pageSize,
    pageIndex
  });
  return {
    items: pageItems(rows, state),
    pageIndex: state.pageIndex,
    pageCount: pageCount(lengthOf(rows), pageSize),
    canNext: canNext(state),
    canPrevious: canPrevious(state)
  };
}

function csvCell(value: unknown, options: CsvOptions = {}): string {
  const separator = orElse(options.separator, () => ',');
  let text = '';
  choose([[isA(value, Date), () => text = dateAsIsoText(value)], [() => and(differs(value, null), () => differs(value, undefined)), () => text = textFrom(value)]]);
  when(and(orElse(options.safe, () => true), () => FORMULA_START.test(text)), () => text = `'${text}`);
  return when(or(or(or(hasText(text, separator), () => hasText(text, '"')), () => hasText(text, '\n')), () => hasText(text, '\r')), () => `"${replaceFirst(text, /"/g, '""')}"`, () => text);
}

function cellOf<T>(row: T, column: Column<T>): unknown {
  return when(equals(typeof column.accessor, 'function'), () => column.accessor(row), () => row[column.accessor]);
}

function toCsv<T>(rows: T[], columns: Column<T>[], options: CsvOptions = {}): string {
  const separator = orElse(options.separator, () => ',');
  const eol = orElse(options.eol, () => '\r\n');
  const lines = [joinWith(mapEach(columns, c => csvCell(c.header, options)), separator)];
  each(rows, row => {
    lines.push(joinWith(mapEach(columns, c => csvCell(cellOf(row, c), options)), separator));
  });
  return join(joinWith(lines, eol), eol);
}

function csvFileName(base: string, date: Date): string {
  const slug = replaceFirst(lowerCase(trimmed(base)).replace(/[^a-z0-9]+/g, '-'), /^-+|-+$/g, '');
  return `${or(slug, () => 'export')}-${sliceText(dateAsIsoText(date), 0, 10)}.csv`;
}

function createCsvMachine<T>(columns: Column<T>[], options: CsvOptions = {}): AtomMachine<CsvState, CsvEvent<T>, void> {
  const m: AtomMachine<CsvState, CsvEvent<T>, void> = {
    id: 'csv-export',
    init() {
      return {
        status: 'empty',
        csv: '',
        rows: 0
      };
    },
    send(state, event) {
      return when(differs(event.type, 'EXPORT'), () => state, () => when(equals(lengthOf(event.rows), 0), () => when(equals(state.status, 'empty'), () => state, () => m.init()), () => ({
        status: 'ready',
        csv: toCsv(event.rows, columns, options),
        rows: lengthOf(event.rows)
      })));
    },
    stateOf(state) {
      return state.status;
    }
  };
  return m;
}

