function startOfDay(d: Date): Date {
  return dateFrom(times(floorOf(dividedBy(timeOfDate(d), DAY)), DAY));
}

function endOfDay(d: Date): Date {
  return dateFrom(minus(timeOfDate(startOfDay(d)) + DAY, 1));
}

function isValidDate(d: unknown): boolean {
  return and(isA(d, Date), () => not(isNaNNumber(timeOfDate(d))));
}

function statusOf(start: Date | null, end: Date | null): RangeState['status'] {
  return when(and(equals(start, null), () => equals(end, null)), () => 'empty', () => when(or(equals(start, null), () => equals(end, null)), () => 'partial', () => when(or(or(not(isValidDate(start)), () => not(isValidDate(end))), () => isAfter(start, end)), () => 'invalid', () => 'complete')));
}

function range(start: Date | null, end: Date | null): RangeState {
  let s = start;
  let e = end;
  when(and(differs(s, null), () => isValidDate(s)), () => s = startOfDay(s));
  when(and(differs(e, null), () => isValidDate(e)), () => e = endOfDay(e));
  return {
    status: statusOf(s, e),
    start: s,
    end: e
  };
}

function contains(r: RangeState, d: Date): boolean {
  return when(differs(r.status, 'complete'), () => false, () => {
    const t = timeOfDate(d);
    return and(atLeast(t, timeOfDate(r.start as Date)), () => atMost(t, timeOfDate(r.end as Date)));
  });
}

function daysIn(r: RangeState): number {
  return when(differs(r.status, 'complete'), () => 0, () => round(dividedBy(minus(timeOfDate(r.end as Date) + 1, timeOfDate(r.start as Date)), DAY)));
}

function overlaps(a: RangeState, b: RangeState): boolean {
  return when(or(differs(a.status, 'complete'), () => differs(b.status, 'complete')), () => false, () => and(atMost(timeOfDate(a.start as Date), timeOfDate(b.end as Date)), () => atMost(timeOfDate(b.start as Date), timeOfDate(a.end as Date))));
}

function lastDays(days: number, today: Date): RangeState {
  return range(dateFrom(minus(timeOfDate(startOfDay(today)), times(minus(days, 1), DAY))), today);
}

init(input) {
  return range(orElse(get(input, "start"), () => null), orElse(get(input, "end"), () => null));
}

send(state, event) {
  return match(event.type, {
    SET_START: () => range(event.date, state.end),
    SET_END: () => range(state.start, event.date),
    PRESET: () => when(event.days < 1, () => state, () => lastDays(event.days, event.today)),
    CLEAR: () => when(equals(state.status, 'empty'), () => state, () => range(null, null))
  }, () => state);
}

stateOf(state) {
  return state.status;
}

