function isNoFilter(value: FilterValue): boolean {
  return or(or(equals(value, undefined), () => equals(value, '')), () => equals(value, 'all'));
}

function statusOf(filters: Record<string, FilterValue>, search: string): View['status'] {
  const active = hasAnyWhere(valuesOf(filters), v => not(isNoFilter(v)));
  return when(or(active, () => differs(trimmed(search), '')), () => 'filtered', () => 'unfiltered');
}

function view(filters: Record<string, FilterValue>, search: string, sort: Sort | null): View {
  return {
    status: statusOf(filters, search),
    filters,
    search,
    sort
  };
}

function isEmptyValue(v: unknown): boolean {
  return or(isNothing(v), () => equals(v, ''));
}

function compareValues(a: unknown, b: unknown): number {
  const emptyA = isEmptyValue(a);
  const emptyB = isEmptyValue(b);
  return when(and(emptyA, () => emptyB), () => 0, () => when(emptyA, () => 1, () => when(emptyB, () => -1, () => when(and(isA(a, Date), () => isA(b, Date)), () => minus(timeOfDate(a), timeOfDate(b)), () => when(and(isNumber(a), () => isNumber(b)), () => minus(a, b), () => localeCompareText(textFrom(a), textFrom(b), undefined, {
    sensitivity: 'base',
    numeric: true
  }))))));
}

function matchesSearch<T>(row: T, text: string, fields: (keyof T)[]): boolean {
  const needle = lowerCase(trimmed(text));
  return when(equals(needle, ''), () => true, () => hasAnyWhere(fields, f => hasText(lowerCase(textFrom(orElse(row[f], () => ''))), needle)));
}

function applyView<T extends Record<string, unknown>>(rows: T[], v: View, searchFields: (keyof T)[] = []): T[] {
  const active = keepWhere(entriesOf(v.filters), ([, value]) => not(isNoFilter(value)));
  const kept = keepWhere(rows, row => and(isEveryWhere(active, ([id, value]) => equals(row[id], value)), () => matchesSearch(row, v.search, searchFields)));
  return when(equals(v.sort, null), () => kept, () => {
    const {
      id,
      desc
    } = v.sort;
    const indexed = mapEach(kept, (row, i) => ({
      row,
      i
    }));
    indexed.sort((x, y) => {
      const c = compareValues(x.row[id], y.row[id]);
      return when(equals(c, 0), () => minus(x.i, y.i), () => when(and(and(desc, () => not(isEmptyValue(x.row[id]))), () => not(isEmptyValue(y.row[id]))), () => negate(c), () => c));
    });
    return mapEach(indexed, x => x.row);
  });
}

