async function loadMore<T>(state: InfiniteState<T>, load: (cursor: Cursor) => Promise<{
  items: T[];
  nextCursor: Cursor;
}>): Promise<InfiniteState<T>> {
  let asking = machine.send(state, {
    type: 'FETCH_NEXT'
  }) as InfiniteState<T>;
  when(equals(lengthOf(state.pages), 0), () => asking = machine.send(state, {
    type: 'FETCH_FIRST'
  }) as InfiniteState<T>);
  if (equals(asking, state)) {
    return state;
  }
  const cursor = asking.loading as Cursor;
  return await attemptAsync(async () => {
    const page = await load(cursor);
    return machine.send(asking, {
      type: 'RESOLVE',
      cursor,
      items: page.items,
      nextCursor: page.nextCursor
    }) as InfiniteState<T>;
  }, async error => machine.send(asking, {
    type: 'REJECT',
    cursor,
    error
  }) as InfiniteState<T>);
}

function positionOf(index: number, count: number): FlowPosition {
