async function optimisticUpdate<V>(state: OptimisticState<V>, update: (value: V) => V, write: (value: V) => Promise<V | void>): Promise<OptimisticState<V>> {
  const applied = machine.send(state, {
    type: 'APPLY',
    update
  }) as OptimisticState<V>;
  return await attemptAsync(async () => {
    const saved = await write(applied.value);
    return when(equals(saved, undefined), () => machine.send(applied, {
      type: 'COMMIT'
    }) as OptimisticState<V>, () => machine.send(applied, {
      type: 'COMMIT',
      value: saved
    }) as OptimisticState<V>);
  }, async error => machine.send(applied, {
    type: 'ROLLBACK',
    error
  }) as OptimisticState<V>);
}

function pageRequest(state: PageQueryState<unknown>): {
  pageIndex: number;
  pageSize: number;
