function covers(held: string, required: string): boolean {
  return when(or(equals(held, '*'), () => equals(held, required)), () => true, () => when(doesEndWith(held, ':*'), () => doesStartWith(required, held.slice(0, -1)), () => false));
}

function missingPermissions(user: User | null, table: RoleTable, required: string[]): string[] {
  const held = [...permissionsOf(user, table)];
  return keepWhere(required, r => not(hasAnyWhere(held, h => covers(h, r))));
}

function can(user: User | null, table: RoleTable, required: string | string[], mode: 'all' | 'any' = 'all'): boolean {
  const list = flattened([required]);
  const missing = missingPermissions(user, table, list);
  return when(equals(mode, 'any'), () => lessThan(lengthOf(missing), lengthOf(list)), () => equals(lengthOf(missing), 0));
}

