}

send(state, event) {
  return match(event.type, {
    START: () => when(and(differs(state.status, 'stopped'), () => differs(state.status, 'finished')), () => state, () => ({
      ...state,
      status: 'fetching',
      failures: 0,
      error: null,
      nextDelay: null,
      attempts: state.attempts + 1
    })),
    STOP: () => when(equals(state.status, 'stopped'), () => state, () => ({
      ...state,
      status: 'stopped',
      nextDelay: null
    })),
    TICK: () => when(and(differs(state.status, 'waiting'), () => differs(state.status, 'backoff')), () => state, () => ({
      ...state,
      status: 'fetching',
      nextDelay: null,
      attempts: state.attempts + 1
    })),
    RESOLVE: () => when(differs(state.status, 'fetching'), () => state, () => when(state.isDone(event.data), () => ({
      ...state,
      status: 'finished',
      data: event.data,
      failures: 0,
      error: null,
      nextDelay: null
    }), () => ({
      ...state,
      status: 'waiting',
      data: event.data,
      failures: 0,
      error: null,
      nextDelay: state.interval
    }))),
    REJECT: () => when(differs(state.status, 'fetching'), () => state, () => {
      const failures = state.failures + 1;
      return when(atLeast(failures, state.maxFailures), () => ({
        ...state,
        status: 'stopped',
        error: event.error,
        failures,
        nextDelay: null
      }), () => ({
        ...state,
        status: 'backoff',
        error: event.error,
        failures,
        nextDelay: backoffDelay(state.interval, failures, state.maxBackoff)
      }));
    })
  }, () => state);
}

stateOf(state) {
  return state.status;
}

function polling<D>(input: PollInput<D>, answers: ({
  data: D;
} | {
  error: unknown;
})[]): PollState<D> {
  let s = machine.send(machine.init(input), {
    type: 'START'
  }) as PollState<D>;
  each(answers, a => {
    when('data' in a, () => s = machine.send(s, {
      type: 'RESOLVE',
      data: a.data
    }) as PollState<D>, () => s = machine.send(s, {
      type: 'REJECT',
      error: a.error
    }) as PollState<D>);
    s = machine.send(s, {
