function history<V>(past: V[], present: V, future: V[], limit: number): HistoryState<V> {
  return {
    status: statusOf(past, future),
    past,
    present,
    future,
    limit
  };
}

function canUndo(state: HistoryState<unknown>): boolean {
  return greaterThan(lengthOf(state.past), 0);
}

function canRedo(state: HistoryState<unknown>): boolean {
  return greaterThan(lengthOf(state.future), 0);
}

