    when(not(key in out), () => out[key] = issue.message);
  });
  return out;
}

function fromValibot<V, O>(safeParse: (values: V) => {
  success: boolean;
  output?: O;
  issues?: {
    path?: {
      key: string | number;
    }[];
    message: string;
  }[];
}): Schema<V, O> {
  return {
    safeParse(values: V): ParseResult<O> {
      const r = safeParse(values);
      return when(r.success, () => ({
        success: true,
        data: r.output as O
      }), () => {
        const issues = mapEach(orElse(r.issues, () => []), i => ({
          path: mapEach(orElse(i.path, () => []), p => p.key),
          message: i.message
        }));
        return {
          success: false,
          error: {
            issues
          }
        };
      });
    }
  };
}

safeParse(values: V): ParseResult<O> {
  const r = safeParse(values);
  return when(r.success, () => ({
    success: true,
    data: r.output as O
  }), () => {
    const issues = mapEach(orElse(r.issues, () => []), i => ({
      path: mapEach(orElse(i.path, () => []), p => p.key),
      message: i.message
    }));
    return {
      success: false,
      error: {
        issues
      }
    };
  });
}

function validate<V, O, R>(state: SubmitState<V, O, R>, values: V): SubmitState<V, O, R> {
  const parsed = state.schema.safeParse(values);
  return when(parsed.success, () => ({
    ...state,
    status: 'submitting',
    values,
    errors: {},
    data: parsed.data,
    error: null,
    attempts: state.attempts + 1
  }), () => ({
    ...state,
    status: 'invalid',
    values,
    errors: fieldErrors(parsed.error.issues),
    data: null
  }));
}

function clearEdited(errors: Record<string, string>, before: unknown, after: unknown): Record<string, string> {
  const out: Record<string, string> = {};
  each(entriesOf(errors), ([key, message]) => {
    const top = firstOf(splitBy(key, '.'));
    const was = get(before as Record<string, unknown>, top);
    const now = get(after as Record<string, unknown>, top);
    when(isSameValue(was, now), () => out[key] = message);
  });
  return out;
}

init(input) {
  return {
    status: 'idle',
    schema: input.schema,
    values: input.values,
    errors: {},
    data: null,
    result: null,
    error: null,
    attempts: 0
  };
}

send(state, event) {
  return match(event.type, {
    SUBMIT: () => when(equals(state.status, 'submitting'), () => state, () => validate(state, orElse(event.values, () => state.values))),
    RESOLVE: () => when(differs(state.status, 'submitting'), () => state, () => ({
      ...state,
      status: 'submitted',
      result: event.result
    })),
    REJECT: () => when(differs(state.status, 'submitting'), () => state, () => ({
      ...state,
      status: 'failed',
      error: event.error
    })),
    EDIT: () => when(equals(state.status, 'submitting'), () => state, () => ({
      ...state,
      values: event.values,
      errors: clearEdited(state.errors, state.values, event.values)
    })),
    RESET: () => machine.init({
      schema: state.schema,
      values: orElse(event.values, () => state.values)
    })
  }, () => state);
}

stateOf(state) {
  return state.status;
}

async function validatedSubmit<V, O, R>(state: SubmitState<V, O, R>, submit: (data: O) => Promise<R>, values?: V): Promise<SubmitState<V, O, R>> {
  const checked = machine.send(state, {
    type: 'SUBMIT',
    values
  }) as SubmitState<V, O, R>;
  if (differs(checked.status, 'submitting')) {
    return checked;
  }
  return await attemptAsync(async () => {
    const result = await submit(checked.data as O);
    return machine.send(checked, {
      type: 'RESOLVE',
      result
    }) as SubmitState<V, O, R>;
  }, async error => machine.send(checked, {
    type: 'REJECT',
    error
  }) as SubmitState<V, O, R>);
}

